def heuristic(dist_m, turn_deg, swath_len_m, energy_left_frac, depot_dist_m, fits):
    base_score = (dist_m + 1.0) ** -1.0 * (swath_len_m + 1.0) ** -1.0
    turn_penalty = np.sin(np.radians(turn_deg)) * 0.5 + 0.5
    depot_factor = energy_left_frac * depot_dist_m + 1.0
    return base_score * fits * (turn_penalty / 1.0) / (depot_factor + 1.0)

