import numpy as np

def heuristic(dist_m, turn_deg, swath_len_m, energy_left_frac, depot_dist_m, fits):
    eps = 1e-9
    feasibility = 0.5 if fits == 0.0 else 1.0
    turn_penalty = np.clip(np.radians(turn_deg), 0.0, np.pi) + eps
    return (1.0 / (dist_m + 1.0)) * feasibility * (1.0 - turn_penalty)

